// 女主角给朋友打电话（语音）
[
  { title: "朋友被AI抢了饭碗", mood: { name: "苦中作乐", emo: "playful", pts: 2, min: 90 },
    lines: [">我被AI替代了。", "啊？什么时候的事？", ">上周。它比我写得快，还不请假。", "那你现在干嘛？", ">我给它当助理，负责说“写得真好”。", "这岗位工资多少？", ">还是原来的，它不要钱。"] },
  { title: "奶茶续命计划", mood: { name: "糖分满格", emo: "energized", pts: 2, min: 90 },
    lines: ["我今天居然喝了三杯奶茶。",">怎么喝这么多？","一杯自己买的，两杯跟人拼单的。",">你倒是可以留一杯明天喝。","喝着喝着忘了。",">那你今天先别再点了。"] },
  { title: "拼单拼出新朋友", mood: { name: "社交奇遇", emo: "happy", pts: 2, min: 150 },
    lines: [">我今天拼单拼出了个朋友。", "怎么拼的？", ">差五块钱凑满减，隔壁邻居补的。", "然后呢？", ">他说下次还拼，我们建了个群。", "群名叫什么？", ">“满一百减十五互助会”。"] },
  { title: "群消息九十九加", mood: { name: "不敢点开", emo: "playful", pts: 1, min: 60 },
    lines: ["家族群又九十九加了。",">聊什么呢？","没点开，估计又在转视频。",">先看看有没有人找你。","看了，没人找，倒是错过一个红包。",">行，下次看快点。"] },
  { title: "周一综合征急救", mood: { name: "硬撑着笑", emo: "playful", pts: 1, min: 60 },
    lines: [">起来没？今天周一。","起了，还没太清醒。",">我也是，刚差点把牙膏拿成洗面奶。","你先看清再挤。",">看见了，没挤出来。","还好，我也去洗把脸。"] },
  { title: "存款为零俱乐部", mood: { name: "穷得硬气", emo: "confident", pts: 2, min: 120 },
    lines: ["看了眼余额，刚好花完。",">一点都没留？","还有零钱，就是没想到这么快。",">你先看看哪天发钱。","快了，这几天得省一点。",">那别再乱买了，先把饭吃好。"] },
  { title: "相亲对象是同行", mood: { name: "撞车了", emo: "flirty", pts: 2, min: 120 },
    lines: [">你相亲那个怎么样？", "聊着聊着发现他是我们公司对家。", ">哈哈哈，那还能聊吗？", "聊了，互相吐槽各自的老板。", ">然后呢？", "他说下次约我，顺便交换一下行业黑料。", ">这是恋爱还是情报交易？"] },
  { title: "已读不回的猫", mood: { name: "自我安慰", emo: "playful", pts: 2, min: 90 },
    lines: ["他两天没回我了。",">你问什么了？","也没什么，就发了张猫。",">那可能不知道接什么吧。","我就先不发了。",">嗯，等他有空回呗。"] },
  { title: "演唱会抢票战", mood: { name: "手速爆发", emo: "energized", pts: 3, min: 120 },
    lines: [">快开抢了，页面你打开没？","开了，一直转圈。",">我也是，刚才还好好的。","等一下……进去了。",">还有票吗？","没了，真就这么一会儿。",">算了，看看还有没有别的场。"] },
  { title: "健身三天打鱼", mood: { name: "肌肉预备", emo: "playful", pts: 2, min: 90 },
    lines: [">我今天去健身了。","这回待了多久？",">十分钟，后面有点累就回了。","有练到还是光拍照了？",">也练了，手现在还有点酸。","那下次慢慢加，别一下弄太多。"] },
  { title: "剧本杀凶手是我", mood: { name: "演技爆表", emo: "happy", pts: 3, min: 180 },
    lines: [">昨天剧本杀你怎么赢的？", "我是凶手，但全程在装哭。", ">我们还安慰你来着！", "我想了想，演技这块我可以转行。", ">你要是转行，我第一个投资。", "投多少？", ">一杯奶茶。"] },
  { title: "露营忘带帐篷", mood: { name: "星空为被", emo: "playful", pts: 2, min: 120 },
    lines: [">我们到营地了，但出了点小事。", "什么小事？", ">帐篷忘带了，带了二十个烤肠。", "你们是来露营还是来摆摊？", ">现在改叫“露天烧烤夜”。", "晚上睡哪儿？", ">车里。营地费白交了，真浪漫。"] },
  { title: "MBTI又测变了", mood: { name: "人格分裂", emo: "playful", pts: 1, min: 60 },
    lines: [">我MBTI又变了。", "上次不是I人吗？", ">这次测出来是E，还是最外向的那种。", "你昨天不是说不想见任何人？", ">那是测之前的我。", "所以这个测试能测出你心情？", ">不，它测的是我做题时吃没吃饱。"] },
  { title: "朋友圈人设崩塌", mood: { name: "真实一刻", emo: "happy", pts: 2, min: 120 },
    lines: [">刚把一张没修的照片发出去了。","能撤吗？",">已经有人点赞了，不撤了。","我看看。",">桌上还有外卖盒，看见没。","看见了，也没什么，挺像你平时的。"] },
  { title: "副业卖闲鱼", mood: { name: "小老板", emo: "inspired", pts: 2, min: 150 },
    lines: [">旧台灯卖出去了。","卖多少？",">十二块，邮费扣完没剩多少。","那也算清掉一点东西。",">是，桌上空出来一块。","下次先问问运费，别还得倒贴。"] },
  { title: "咖啡喝出灵感", mood: { name: "脑洞大开", emo: "inspired", pts: 3, min: 150 },
    lines: [">我咖啡好像喝多了，手都不太想停。", "你喝几杯了？", ">不说了，先去倒杯水。", "嗯，先别续了，听你说话都比平时快。"] },
  { title: "信用卡账单日", mood: { name: "视死如归", emo: "confident", pts: 2, min: 90 },
    lines: ["账单出来了，比我想的多。",">是不是有几笔忘算了？","对，翻了半天才对上。",">分期那些也算上啊。","就是漏了那几笔。",">下回先记着，别等出账再猜。"] },
  { title: "茶水间的八卦", mood: { name: "吃瓜吃撑", emo: "energized", pts: 2, min: 120 },
    lines: [">你们公司有什么新消息？","才知道财务小李跟行政老王是亲戚。",">之前没看出来？","没有，他俩天天互相说对方迟到。",">亲戚也不帮着点啊。","是，熟起来说话更不留情。"] },
  { title: "断亲后的年夜饭", mood: { name: "清净了", emo: "happy", pts: 2, min: 150 },
    lines: [">今年春节你回老家吗？", "不回，我跟亲戚都断得很干净了。", ">那年夜饭呢？", "自己煮火锅，一个人也有仪式感。", ">不孤单吗？", "不会，没人问我什么时候结婚。", ">这条确实香。"] },
  { title: "出租屋里的蟑螂", mood: { name: "室友升级", emo: "playful", pts: 2, min: 90 },
    lines: [">你家那只蟑螂找着了吗？","没有，刚才又从柜子底下钻过去了。",">药放了吗？","放了，就是老怕它突然飞。",">那你先别光脚踩地上。","我已经把拖鞋穿好了，还拿着另一只。"] },
  { title: "熬夜冠军赛", mood: { name: "黑眼圈荣誉", emo: "happy", pts: 1, min: 90 },
    lines: [">你昨晚几点睡的？","快四点，刷着刷着就忘了。",">我也没早多少，今天脑子都慢。","你也别再熬了。",">你先做到再说我。","好，今晚互相提醒一下。"] },
  { title: "AI帮我写情书", mood: { name: "肉麻过头", emo: "flirty", pts: 2, min: 120 },
    lines: [">我让AI给他写了封情书。", "写得怎么样？", ">第一句是“亲爱的用户”。", "哈哈哈，那他怎么回？", ">他回了“收到，已为您处理”。", "你俩是在谈恋爱还是客服对话？", ">客服也有真爱。"] },
  { title: "搬家的纸箱子", mood: { name: "箱子成精", emo: "energized", pts: 2, min: 120 },
    lines: [">我搬家了，纸箱堆得像山。", "你东西有那么多吗？", ">八个箱子是零食盒和快递盒。", "那你的衣服呢？", ">在一个袋子里，装得比较随意。", "你是个有取舍的人。", ">我是个舍不得扔盒子的人。"] },
  { title: "社恐点外卖", mood: { name: "不想开门", emo: "playful", pts: 1, min: 60 },
    lines: ["我点了外卖，备注“放门口”。", ">外卖小哥打电话了吗？", "打了，我没接，他发短信，我也没回。", ">那你怎么拿？", "我听到脚步声走远，才开门。", ">你这像在拍谍战片。", "对，代号“饭到了”。"] },
  { title: "考公第N次上岸", mood: { name: "越挫越勇", emo: "confident", pts: 3, min: 180 },
    lines: [">成绩出来了，还是差一点。","差多少？",">三分，前面还白紧张半天。","你现在怎么打算？",">先歇两天吧，这阵子都没好好睡。","嗯，歇够了再想下一步。"] },
  { title: "宠物改名风波", mood: { name: "名字好大", emo: "happy", pts: 2, min: 120 },
    lines: [">我给我家狗改名了。", "原来叫什么？", ">旺财。现在叫“张总”。", "为什么？", ">每次我喊张总，它比我老板还听话。", "你这是在报复老板吗？", ">我是在积累领导力经验。"] },
  { title: "暧昧期表情包战", mood: { name: "斗图高手", emo: "flirty", pts: 2, min: 120 },
    lines: ["他又发个熊猫举爱心的表情。",">那你回什么？","想回一个，一直没挑好。",">说句话也行啊。","也是，我先问他吃饭没。",">嗯，别光在表情里找半天。"] },
  { title: "微信步数第一名", mood: { name: "称霸榜首", emo: "energized", pts: 2, min: 90 },
    lines: [">你今天步数怎么这么高？","走错路了，多绕好大一圈。",">没开导航？","开了，以为有条近路就没听。",">那你可真走出经验了。","现在腿有点酸，下回老实跟着走。"] },
  { title: "朋友发明新职业", mood: { name: "创业灵感", emo: "inspired", pts: 2, min: 150 },
    lines: [">我打算开个新业务，专门陪人吵架。", "吵架还能陪？", ">对，有人想吵但没对象，我来陪。", "价格呢？", ">按分钟，吵赢了半价。", "我怕你把客户气跑了。", ">放心，我会输得很有技巧。"] },
  { title: "朋友刚被裁员", mood: { name: "心里发凉", emo: "sad", pts: 2, min: 180 },
    lines: [">我那边让下个月别去了。", "啊？通知得这么突然？", ">嗯，东西还没收拾呢。", "你先吃点东西，待会儿有空我再找你聊。"] },
  { title: "房东扣了押金", mood: { name: "气到发抖", emo: "angry", pts: 3, min: 120 },
    lines: [">房东不退我押金了！", "理由是什么？", ">说墙上有钉子眼。", "那是你挂画的，正常使用啊。", ">他说那是“人为损坏”。", "他自己墙皮都掉了一半！", ">我已经把对话全录下来了。"] },
  { title: "被喊去搬钢琴", mood: { name: "腰在颤抖", emo: "tense", pts: 2, min: 90 },
    lines: [">你周末有空吗？", "什么事？", ">帮我搬个东西，不重。", "你上次也说不重，结果是冰箱。", ">这次真的轻，一架钢琴而已。", "钢琴还轻？没有电梯吧？", ">……有，但是它坏了。"] },
  { title: "群发错了对象", mood: { name: "社死现场", emo: "embarrassed", pts: 2, min: 90 },
    lines: ["我把吐槽的话发工作群了。",">撤回了吗？","撤了，但已经有人看见了。",">看见了也先别再解释一大段。","我刚正想补一句。",">先等等，越补越显眼。"] },
  { title: "周日的无聊电话", mood: { name: "放空中", emo: "bored", pts: 1, min: 60 },
    lines: [">你在干嘛？", "没什么，在家待着。", ">我也没事，就顺手拨过来了。", "那聊两句呗，你刚才那个东西找到了吗？"] },
  { title: "深夜聊到发懵", mood: { name: "思绪漂浮", emo: "dazed", pts: 2, min: 90 },
    lines: [">你怎么也还醒着？", "都三点了，我也不知道在磨蹭什么。", ">我刚才一直刷手机，停不下来。", "行，咱互相提醒一下，先把手机放下吧。"] },
  { title: "一起赶方案", mood: { name: "拼到天亮", emo: "focused", pts: 3, min: 180 },
    lines: [">我这个方案还剩十页。", "我帮你看，你写，我查资料。", ">好，你负责数据，我负责文案。", "第三页那组数字好像不对。", ">我再核对一下……真的错了！", "改完了就能交了，加油。", ">谢谢你，今晚陪我熬夜。"] },
  { title: "朋友分手了", mood: { name: "陪着难受", emo: "sad", pts: 3, min: 240 },
    lines: [">我和那个人分了。", "啊，什么时候的事？", ">刚说完，还有点懵。", "你要是想说就说，我这会儿没别的事。"] },
  { title: "被催婚的电话", mood: { name: "压力山大", emo: "uncomfortable", pts: 2, min: 120 },
    lines: ["我妈刚刚又催我找对象了。", ">这个月第几次了？", "第九次，都过了一半了。", ">你怎么回的？", "我说我在找，在找工作。", ">她信了吗？", "她说那就两个一起找。"] },
  { title: "半夜听到敲门声", mood: { name: "后背发凉", emo: "scared", pts: 2, min: 90 },
    lines: ["我家门外好像有人敲门。", ">现在几点？", "凌晨两点。", ">别开！看猫眼了吗？", "没人，只有风声。", ">你先别挂电话，我陪你。", "谢谢……啊，是外卖员走错门了。"] },
  { title: "陪我写简历", mood: { name: "认真起来", emo: "focused", pts: 3, min: 180 },
    lines: [">我简历写半天，还是那么几行。", "把你做过的先列出来，别急着改得好看。", ">那我先把项目写上。", "嗯，发我看看，我帮你挑挑。"] },
  { title: "和室友吵了一架", mood: { name: "气鼓鼓", emo: "angry", pts: 2, min: 120 },
    lines: ["我真的受不了我室友了。", ">她又怎么了？", "半夜外放短剧，还用我的锅。", ">那你跟她说了吗？", "说了，她说“哦”。", ">这个“哦”，我听了都想骂人。", "对！所以我现在站在阳台生闷气。"] },
  { title: "被安慰到了", mood: { name: "底气回来", emo: "confident", pts: 3, min: 180 },
    lines: [">我今天汇报开错页了，尴尬死。", "后来换回来了吗？", ">换了，后面倒也讲完了。", "那先别反复想，越想越觉得自己显眼。"] },
  { title: "等一个快递", mood: { name: "盼到发愁", emo: "bored", pts: 1, min: 60 },
    lines: ["我的快递三天没动了。", ">显示什么状态？", "“已到达某转运中心”，三天了。", ">它是不是在度假？", "估计在中心里排队吃饭。", ">那你要不要联系客服？", "联系了，客服说它在“路上”。"] },
  { title: "被临时顶班了", mood: { name: "硬着头皮", emo: "tense", pts: 2, min: 120 },
    lines: ["同事请假，让我帮忙顶一下。",">你知道怎么弄吗？","不太知道，密码还没问到。",">先找人问清楚，别自己乱点。","嗯，我已经发消息问了。",">等回了再弄，省得返工。"] },
  { title: "老友深夜来电", mood: { name: "心头一暖", emo: "happy", pts: 3, min: 240 },
    lines: [">我刚下班，走路回去呢。", "这么晚啊，走哪儿了？", ">快到楼下了，跟你说两句。", "行，过马路先别说话，我等你。"] },
  { title: "记不起要说什么", mood: { name: "脑袋空空", emo: "dazed", pts: 1, min: 60 },
    lines: ["喂，我有件事要跟你说。", ">什么事？", "……我忘了。", ">你打电话来就为了说你忘了？", "我刚才明明很急的。", ">那你想起来再打给我。", "好，我现在去翻翻聊天记录。"] },
  { title: "替朋友挡酒局", mood: { name: "头皮发紧", emo: "embarrassed", pts: 2, min: 90 },
    lines: [">这饭局还没结束，我想找个借口先走。", "你直接说还有事呗。", ">已经说过两次了。", "那你东西先拿好，说完就走，别又坐回去了。"] },
  { title: "一起刷题备考", mood: { name: "并肩作战", emo: "focused", pts: 3, min: 180 },
    lines: [">这题我做三遍还错。", "哪题？发我。", ">发了，你看最后一问。", "哦，我也得想想，先别催我。"] },
  { title: "搬走的老同学", mood: { name: "有点失落", emo: "sad", pts: 2, min: 150 },
    lines: [">我下个月可能去别的城市了。", "工作定下来了？", ">差不多了，还在找住的地方。", "哪片啊？房子照片发我看看。"] },
  { title: "没人记得的生日", mood: { name: "蛋糕有点咸", emo: "sad", pts: 2, min: 150 },
    lines: [">哎，今天我生日。", "生日快乐！你要不说我真差点忘了。", ">哈哈，我自己也差点忘。", "吃点好的呗，你打算吃啥？"] },
]
